('advanced-native-1611', '["phrase"]'::jsonb, '{"advanced-native-1611-v1-audio":{"type":"mc","answers":["收納與保留操作位置一起讓有限空間實用。"],"options":["收納與保留操作位置一起讓有限空間實用。","只要把地面放滿物品，就已符合句子的安排。","句子要求把活動位置改成更多儲物，不再留工作區。","工作室很大，所以安排時完全毋須考慮空間用途。"]},"advanced-native-1611-v2-reply":{"type":"mc","answers":["We balance keeping materials nearby with having room to work.","We make every inch count through useful storage and a clear working area.","We use the walls for supplies so the floor can support movement.","The layout gives each area a practical role rather than filling every gap."],"options":["We balance keeping materials nearby with having room to work.","We make every inch count through useful storage and a clear working area.","We use the walls for supplies so the floor can support movement.","The layout gives each area a practical role rather than filling every gap."]},"advanced-native-1611-v1-scene":{"type":"mc","answers":["We want to make every inch count without crowding out the visitors."],"options":["The best use of space is to fill the standing area with repeated decoration.","The layout should be judged only by how many shelves it holds, not by whether visitors can see the work.","We want to make every inch count without crowding out the visitors."]},"advanced-native-1611-v1-contrast":{"type":"mc","answers":["一定要把每個空位塞滿，不能留通道。"],"options":["操作或活動空間也可以是有效使用。","有限位置需按用途仔細安排。","一定要把每個空位塞滿，不能留通道。"]},"advanced-native-1611-v1-branch":{"type":"mc","answers":["To make every inch count, we should include space people need to move and use the display, not only space for objects."],"options":["To make every inch count, we should include space people need to move and use the display, not only space for objects.","Put another shelf in the walkway before checking how visitors reach the display.","Count only the area covered by objects and ignore the space needed to use them."]},"advanced-native-1611-v1-final":{"type":"open","answers":["We need to make every inch count on this small map, keeping the route clear and removing repeated decoration rather than shrinking every label.","To make every inch count, let us give priority to readable directions and the essential landmarks, with enough space to tell the symbols apart."],"options":[]}}'::jsonb),
('advanced-native-1612', '["phrase"]'::jsonb, '{"advanced-native-1612-v1-audio":{"type":"mc","answers":["他們同時考慮實際空間及外觀喜好。"],"options":["他們把喜歡的顏色當成尺寸已合適的唯一證據。","他們同時考慮實際空間及外觀喜好。","他們只按顏色選，沒有核對可用空間。","他們排除外觀考慮，只看物品是否放得下。"]},"advanced-native-1612-v2-reply":{"type":"mc","answers":["They chose with their heads and their eyes, weighing practical space and appearance.","They checked the room’s limits and also discussed the colours they liked.","Their choice combined practical judgement with visual preference.","They wanted something that worked in the room and looked right to them."],"options":["They chose with their heads and their eyes, weighing practical space and appearance.","They checked the room’s limits and also discussed the colours they liked.","Their choice combined practical judgement with visual preference.","They wanted something that worked in the room and looked right to them."]},"advanced-native-1612-v1-scene":{"type":"mc","answers":["They choose with their heads and their eyes."],"options":["Their visual preference replaces any need to compare the dimensions.","They refuse to consider appearance because storage is also important.","They choose with their heads and their eyes."]},"advanced-native-1612-v1-contrast":{"type":"mc","answers":["只要外觀吸引，就可把實際用途當作已確認。"],"options":["只要外觀吸引，就可把實際用途當作已確認。","可以分別說明尺寸、用途及外觀各帶來甚麼考慮。","選擇可有實際判斷及視覺偏好兩部分。"]},"advanced-native-1612-v1-branch":{"type":"mc","answers":["We can choose with our heads and our eyes, checking what fits while comparing the colours we enjoy."],"options":["Treat every discussion of appearance as proof that practical needs have been ignored.","We can choose with our heads and our eyes, checking what fits while comparing the colours we enjoy.","Leave the measurements out once you have a favourite colour."]},"advanced-native-1612-v1-final":{"type":"open","answers":["Let us choose with our heads and our eyes: we can test whether readers understand the title while asking which colours and images draw them in