('advanced-native-1655', '["phrase"]'::jsonb, '{"advanced-native-1655-v1-audio":{"type":"mc","answers":["人物有持續安排的檢查及下次預約。"],"options":["人物有持續安排的檢查及下次預約。","每次到訪都由當天突發事故決定，沒有後續安排。","他只有打算預約，尚未記下任何下次日期。","阿米爾只有一次為工作申請而安排的檢查，沒有持續預約。"]},"advanced-native-1655-v2-reply":{"type":"mc","answers":["He treats the next visit as something to plan for rather than an unexpected interruption.","He gets regular check-ups according to a plan agreed with his clinician.","His visits are recurring appointments, not just unexpected emergencies.","He keeps track of the next visit in the agreed plan."],"options":["He treats the next visit as something to plan for rather than an unexpected interruption.","He gets regular check-ups according to a plan agreed with his clinician.","His visits are recurring appointments, not just unexpected emergencies.","He keeps track of the next visit in the agreed plan."]},"advanced-native-1655-v1-scene":{"type":"mc","answers":["She gets regular check-ups as part of an ongoing plan."],"options":["She gets regular check-ups as part of an ongoing plan.","Each visit was arranged only after an unexpected emergency that day.","She has discussed possible visits but has not yet agreed any dates."]},"advanced-native-1655-v1-contrast":{"type":"mc","answers":["每位讀者應在何時接受哪些檢查。"],"options":["檢查不是只有一次，而有持續安排。","每位讀者應在何時接受哪些檢查。","check-ups 在這裏是健康檢查的名詞。"]},"advanced-native-1655-v1-branch":{"type":"mc","answers":["He gets regular check-ups under an agreed plan; the text does not present these visits as sudden emergencies."],"options":["He gets regular check-ups under an agreed plan; the text does not present these visits as sudden emergencies.","The next date was chosen only after an unexpected urgent problem arose that morning.","He is only considering asking for an appointment and has no next date to record."]},"advanced-native-1655-v1-final":{"type":"open","answers":["I get regular check-ups under an agreed plan, and my next appointment is on Wednesday. Could I help with