('advanced-native-1664', '["phrase"]'::jsonb, '{"advanced-native-1664-v1-audio":{"type":"mc","answers":["她把時間及心力充分投入已選的製作。"],"options":["她仍只旁觀，尚未答應花時間參與。","她把排練全部壓在同一晚完成，而非持續投入。","她把時間及心力充分投入已選的製作。","她已演完劇目，句子只在報告觀眾結果。"]},"advanced-native-1664-v2-reply":{"type":"mc","answers":["She gave the rehearsals a firm place in her schedule.","She worked closely with the cast rather than stay at the edge of the project.","She committed strongly to making the agreed production happen.","She went all in on the production and committed her free evenings to it."],"options":["She gave the rehearsals a firm place in her schedule.","She worked closely with the cast rather than stay at the edge of the project.","She committed strongly to making the agreed production happen.","She went all in on the production and committed her free evenings to it."]},"advanced-native-1664-v1-scene":{"type":"mc","answers":["He is ready to go all in on the exhibition after checking what it involves."],"options":["His commitment confirms that the exhibition has already attracted its audience.","He has decided to make only an occasional suggestion without joining the work.","He is ready to go all in on the exhibition after checking what it involves."]},"advanced-native-1664-v1-contrast":{"type":"mc","answers":["人物已完成整項活動並得到成功結果。"],"options":["人物對指定事情充分投入。","人物已完成整項活動並得到成功結果。","情境應交代他投入的時間、心力或其他選擇。"]},"advanced-native-1664-v1-branch":{"type":"mc","answers":["Going all in shows her commitment, but we should still agree which responsibilities belong to each person."],"options":["Treat her enthusiasm as acceptance of the tasks nobody else has chosen.","Wait for her to complete the production before asking what help she wanted.","Going all in shows her commitment, but we should still agree which responsibilities belong to each person."]},"advanced-native-1664-v1-final":{"type":"open","answers":["After the trial walks, I would like to go all in on the sound-recording project and join the weekly sharing. Could y